async () => {
  const out = {};
  const parse = (html) => { const d = new DOMParser().parseFromString(html,'text/html'); return d; };
  const rows = (d)=>[...d.querySelectorAll('tr')].filter(r=>r.cells.length==5 && r.querySelector('a[href*="Delete"]')).map(r=>[...r.cells].slice(1,4).map(c=>c.textContent.trim()).join('|'));
  let d = document;
  const form = () => d.querySelector('form');
  out[1] = rows(d);
  for (let p=2;p<=17;p++){
    const fd = new FormData(document.querySelector('form'));
    fd.set('__EVENTTARGET','gv'); fd.set('__EVENTARGUMENT','Page$'+p);
    const r = await fetch(location.href,{method:'POST',body:new URLSearchParams(fd)});
    out[p] = rows(parse(await r.text()));
  }
  return out;
}

